def max_sub(xs):
    if not xs:
        raise ValueError("List must not be empty")

    max_sum = current_sum = xs[0]
    for x in xs[1:]:
        current_sum = max(x, current_sum + x)
        max_sum = max(max_sum, current_sum)

    return max_sum
```

